<!-- 财务运维任务发起页面，负责串联任务草稿、前提、范围、计划与审批流程。 -->
<template>
  <section class="task-workbench" aria-labelledby="workbench-title">
    <div class="page-heading"><div><p class="eyebrow">任务发起与范围确认</p><h2 id="workbench-title">建立一个有边界的调查任务</h2><p class="page-description">先说明问题和来源，再确认系统、对象、路径、时间及字段权限。</p></div><div><el-tag v-if="task" :type="task.status === 'DRAFT' ? 'warning' : 'success'">{{ task.status }}</el-tag><el-button v-if="task" type="text" @click="openDiagnostics">查看任务诊断</el-button></div></div>
    <el-alert v-if="staleMessage" :title="staleMessage" type="warning" :closable="false" show-icon />
    <el-alert v-if="errorMessage" :title="errorMessage" type="error" :closable="false" show-icon />
    <el-row :gutter="20"><el-col :span="15"><el-card shadow="never" class="form-card">
      <el-steps :active="activeStep" finish-status="success" simple><el-step title="任务问题" /><el-step title="前提来源" /><el-step title="范围确认" /></el-steps>
      <el-form :model="form" label-position="top" class="task-form">
        <template v-if="activeStep === 0"><el-form-item label="任务标题"><el-input v-model.trim="form.title" :maxlength="300" placeholder="例如：核查审批配置异常" /></el-form-item><el-form-item label="原始问题"><el-input v-model.trim="form.question" type="textarea" :rows="6" :maxlength="8000" placeholder="描述需要核查的业务问题和预期结果" /></el-form-item><el-button type="primary" :loading="saving" @click="createTaskDraft">创建任务草稿</el-button></template>
        <template v-else-if="activeStep === 1"><el-form-item label="前提类型"><el-input v-model.trim="form.premiseType" /></el-form-item><el-form-item label="前提主体"><el-input v-model.trim="form.subjectKey" /></el-form-item><el-form-item label="前提说明"><el-input v-model.trim="form.statement" type="textarea" :rows="3" /></el-form-item><el-form-item label="来源说明"><el-input v-model.trim="form.sourceDescription" type="textarea" :rows="3" /></el-form-item><el-button type="primary" :loading="saving" @click="savePremise">保存前提并进入范围确认</el-button></template>
        <template v-else><el-form-item label="系统编码"><el-input v-model.trim="form.systemCode" placeholder="例如：FIN-SYN" /></el-form-item><el-form-item v-for="field in scopeFields" :key="field.key" :label="field.label"><el-input v-model.trim="form[field.key]" type="textarea" :rows="2" /></el-form-item><el-form-item label="契约版本"><el-input v-model.trim="form.schemaVersion" /></el-form-item><el-button type="primary" :loading="saving" @click="saveScope">确认范围修订</el-button></template>
      </el-form>
        <div v-if="task && task.scopeRevisionNo" class="execution-panel">
        <h4 class="section-heading">计划与审批</h4>
        <p class="panel-hint">只展示计划目标、范围绑定、调用上限和公开结果，不展示推理链或原始模型响应。</p>
        <el-form label-position="top"><el-form-item label="推荐步骤"><el-input v-model.trim="planGoals[0]" placeholder="填写一个推荐的可执行步骤" /></el-form-item><el-form-item label="备选步骤一"><el-input v-model.trim="planGoals[1]" /></el-form-item><el-form-item label="备选步骤二"><el-input v-model.trim="planGoals[2]" /></el-form-item><el-button type="primary" :loading="saving" @click="submitPlan">提交计划</el-button></el-form>
        <el-card v-if="proposal" shadow="never" class="approval-card"><h4>审批卡</h4><el-alert title="请确认将读取什么、从哪里读取以及最多调用次数" type="info" :closable="false" /><el-radio-group v-model="approval.decision"><el-radio label="APPROVED">批准</el-radio><el-radio label="REJECTED">拒绝</el-radio></el-radio-group><el-form label-position="top"><el-form-item label="选择步骤"><el-select v-model="selectedStepId"><el-option v-for="step in proposal.steps" :key="step.stepId" :label="step.goal" :value="step.stepId" /></el-select></el-form-item><el-form-item label="目标摘要 SHA-256"><el-input v-model.trim="approval.goalHash" :maxlength="64" /></el-form-item><el-form-item label="来源绑定标识"><el-input v-model.trim="approval.sourceBindingId" placeholder="填写已授权来源绑定 UUID" /></el-form-item><el-form-item label="字段策略版本"><el-input v-model.trim="approval.fieldPolicyVersion" /></el-form-item><el-form-item label="查询模板版本"><el-input v-model.trim="approval.queryTemplateVersion" /></el-form-item><el-form-item label="最大调用次数"><el-input-number v-model="approval.maxCalls" :min="1" :max="100" /></el-form-item><el-button type="primary" :loading="saving" @click="submitApproval">提交审批决定</el-button><el-alert v-if="approvalResult" title="审批决定已保存，任务版本已更新" type="success" :closable="false" show-icon /></el-form></el-card>
        <h4 class="section-heading">公开实时进度</h4><el-tag size="small" type="info">{{ eventStatus }}</el-tag><ol v-if="events.length" class="event-timeline"><li v-for="event in events" :key="event.sequence"><time>{{ event.occurredAt }}</time><span>{{ event.eventType }}：{{ event.publicReason || event.resultReference || event.status || '状态已更新' }}</span></li></ol><div v-else class="empty-state" role="status">等待公开任务事件</div>
      </div>
    </el-card></el-col><el-col :span="9"><el-card shadow="never" class="detail-card"><div class="card-heading"><h3>当前任务</h3><span v-if="task">v{{ task.rowVersion }}</span></div><div v-if="!task" class="empty-state" role="status">完成第一步后显示任务详情</div><template v-else><dl class="task-summary"><dt>任务标题</dt><dd>{{ task.title }}</dd><dt>任务标识</dt><dd class="mono">{{ task.taskId }}</dd><dt>范围修订</dt><dd>{{ task.scopeRevisionNo || '尚未确认' }}</dd><dt>范围摘要</dt><dd class="mono">{{ task.scopeDigest || '尚未生成' }}</dd></dl><el-button v-if="task.scopeRevisionNo" type="text" @click="$router.push(`/tasks/${task.taskId}/evidence`)">查看证据与覆盖度</el-button></template></el-card></el-col></el-row>
  </section>
</template>

<script lang="ts">
import Vue from 'vue'
import { PublicTaskEvent, StepApprovalResponse, StepProposalResponse, TaskResponse } from '../api/generated'
import { getCurrentIdentity } from '../services/identity'
import { addPremise, ConfirmScopePayload, confirmScope, createTask, isStaleError, parseJsonField } from '../services/task-api'
import { approveStep, ApproveStepPayload, proposeSteps } from '../services/execution-api'
import { openSse, SseConnection } from '../services/sse'

interface WorkbenchForm { title: string; question: string; premiseType: string; subjectKey: string; statement: string; sourceDescription: string; systemCode: string; objectSelector: string; effectiveTimeRange: string; includedPaths: string; excludedPaths: string; allowedReadFields: string; allowedRetainFields: string; allowedModelFields: string; schemaVersion: string }
type ScopeField = 'objectSelector' | 'effectiveTimeRange' | 'includedPaths' | 'excludedPaths' | 'allowedReadFields' | 'allowedRetainFields' | 'allowedModelFields'

export default Vue.extend({
  name: 'WorkbenchHome',
  data() { return { activeStep: 0, saving: false, task: null as TaskResponse | null, proposal: null as StepProposalResponse | null, approvalResult: null as StepApprovalResponse | null, selectedStepId: '', planGoals: ['', '', ''], events: [] as PublicTaskEvent[], eventStatus: '未连接', sseConnection: null as SseConnection | null, approval: { goalHash: '', sourceBindingId: '', fieldPolicyVersion: 'field-v1', queryTemplateVersion: 'query-v1', maxCalls: 2, decision: 'APPROVED' as 'APPROVED' | 'REJECTED' }, errorMessage: '', staleMessage: '', scopeFields: [{ key: 'objectSelector' as ScopeField, label: '对象选择器 JSON' }, { key: 'effectiveTimeRange' as ScopeField, label: '生效时间范围 JSON' }, { key: 'includedPaths' as ScopeField, label: '纳入路径 JSON 数组' }, { key: 'excludedPaths' as ScopeField, label: '排除路径 JSON 数组' }, { key: 'allowedReadFields' as ScopeField, label: '允许读取字段 JSON 数组' }, { key: 'allowedRetainFields' as ScopeField, label: '允许保留字段 JSON 数组' }, { key: 'allowedModelFields' as ScopeField, label: '允许模型字段 JSON 数组' }], form: { title: '', question: '', premiseType: '业务规则', subjectKey: '', statement: '', sourceDescription: '', systemCode: '', objectSelector: '{"module":"approval"}', effectiveTimeRange: '{"from":"2026-01-01","to":"2026-12-31"}', includedPaths: '["workflow.approvals"]', excludedPaths: '[]', allowedReadFields: '["workflow.id"]', allowedRetainFields: '["workflow.id"]', allowedModelFields: '["workflow.id"]', schemaVersion: 'scope-v1' } as WorkbenchForm } },
  methods: {
    /** 打开当前任务的诊断页面。 */
    openDiagnostics(): void { if (this.task) void this.$router.push('/tasks/' + this.task.taskId + '/diagnostics') },
    /** 创建任务草稿并推进到前提来源步骤。 */
    async createTaskDraft(): Promise<void> { const identity = getCurrentIdentity(); if (!identity || !this.form.title || !this.form.question) { this.errorMessage = '请先填写任务标题、原始问题并确认当前身份'; return }; await this.execute(async () => { this.task = await createTask({ title: this.form.title, originalQuestion: this.form.question, initiatorUserId: identity.userId, runtimeBundleId: '00000000-0000-4000-8000-000000000010' }); this.activeStep = 1; this.connectEvents() }) },
    /** 保存前提来源并推进到范围确认步骤。 */
    async savePremise(): Promise<void> { if (!this.task || !this.form.subjectKey || !this.form.statement || !this.form.sourceDescription) { this.errorMessage = '请完整填写前提来源'; return }; await this.execute(async () => { this.task = await addPremise(this.task!.taskId, { premiseType: this.form.premiseType, subjectKey: this.form.subjectKey, statement: this.form.statement, sourceDescription: this.form.sourceDescription }, this.task!.rowVersion); this.activeStep = 2 }) },
    /** 提交范围 JSON 并显示新的不可变修订。 */
    async saveScope(): Promise<void> { if (!this.task || !this.form.systemCode) { this.errorMessage = '请填写系统编码'; return }; try { const payload: ConfirmScopePayload = { systemCode: this.form.systemCode, objectSelector: parseJsonField(this.form.objectSelector, '对象选择器'), effectiveTimeRange: parseJsonField(this.form.effectiveTimeRange, '生效时间范围'), includedPaths: parseJsonField(this.form.includedPaths, '纳入路径'), excludedPaths: parseJsonField(this.form.excludedPaths, '排除路径'), allowedReadFields: parseJsonField(this.form.allowedReadFields, '允许读取字段'), allowedRetainFields: parseJsonField(this.form.allowedRetainFields, '允许保留字段'), allowedModelFields: parseJsonField(this.form.allowedModelFields, '允许模型字段'), schemaVersion: this.form.schemaVersion }; await this.execute(async () => { this.task = await confirmScope(this.task!.taskId, payload, this.task!.rowVersion) }) } catch (error: unknown) { this.errorMessage = error instanceof Error ? error.message : '范围校验未完成，请检查输入' } },
    /** 提交推荐步骤和最多两个备选步骤。 */
    async submitPlan(): Promise<void> { if (!this.task || !this.planGoals[0].trim()) { this.errorMessage = '请先填写推荐步骤'; return }; const steps = this.planGoals.map((goal, index) => ({ goal: goal.trim(), recommended: index === 0 })).filter((step) => step.goal); await this.execute(async () => { this.proposal = await proposeSteps(this.task!.taskId, { steps }, this.task!.rowVersion); this.syncTaskProgress(this.proposal.status, this.proposal.rowVersion, this.proposal.scopeRevisionId); this.selectedStepId = this.proposal.currentStepId || this.proposal.steps[0]?.stepId || '' }) },
    /** 提交审批卡中的绑定和批准或拒绝决定。 */
    async submitApproval(): Promise<void> { if (!this.task || !this.proposal || !this.selectedStepId || !/^[a-fA-F0-9]{64}$/.test(this.approval.goalHash) || !this.approval.sourceBindingId) { this.errorMessage = '请完整填写步骤摘要、来源绑定和审批信息'; return }; const payload: ApproveStepPayload = { stepId: this.selectedStepId, goalHash: this.approval.goalHash, sourceBindingId: this.approval.sourceBindingId, scopeRevisionId: this.task.currentScopeRevisionId || '', fieldPolicyVersion: this.approval.fieldPolicyVersion, queryTemplateVersion: this.approval.queryTemplateVersion, maxCalls: this.approval.maxCalls, expiresAt: null, expectedRowVersion: this.task.rowVersion, decision: this.approval.decision }; await this.execute(async () => { this.approvalResult = await approveStep(this.task!.taskId, payload); this.syncTaskProgress(this.task!.status, this.approvalResult.rowVersion) }) },
    /** 将步骤接口返回的最新状态和行版本同步回当前任务视图。 */
    syncTaskProgress(status: TaskResponse['status'], rowVersion: number, scopeRevisionId?: string | null): void { if (!this.task) return; this.task = { ...this.task, status, rowVersion, currentScopeRevisionId: scopeRevisionId === undefined ? this.task.currentScopeRevisionId : scopeRevisionId } },
    /** 建立公开事件流并在断线时保留最近游标。 */
    connectEvents(): void { if (!this.task) return; this.sseConnection?.close(); this.eventStatus = '连接中'; const base = import.meta.env.VITE_API_BASE_URL || '/api'; this.sseConnection = openSse(`${base}/tasks/${this.task.taskId}/events/stream`, { onOpen: () => { this.eventStatus = '已连接' }, onMessage: (event) => { if (event.taskId !== this.task?.taskId) return; this.events = [...this.events, event].slice(-50) }, onReconnect: () => { this.eventStatus = '等待新进度' }, onError: () => { this.eventStatus = '实时消息暂时无法识别' } }) },
    /** 统一处理保存中的加载、错误和 stale 状态。 */
    async execute(action: () => Promise<void>): Promise<void> { if (this.saving) return; this.saving = true; this.errorMessage = ''; this.staleMessage = ''; try { await action() } catch (error: unknown) { if (isStaleError(error)) this.staleMessage = '范围或任务版本已变化，请刷新当前任务后再提交'; else this.errorMessage = error instanceof Error ? error.message : '请求未完成，请稍后重试' } finally { this.saving = false } },
  },
  beforeDestroy() { this.sseConnection?.close() },
})
</script>
